// ONE-TIME SETUP ENDPOINT — creates the study's Resend templates, event, and automation.
// Visit  https://notebook.meded.studio/api/setup?setup=nsu-go  ONCE, then DELETE this file.
// Uses RESEND_API_KEY already set in this project. Creates the automation DISABLED so you
// can review it in Resend and switch it on yourself.

const { Resend } = require("resend");

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const FROM = "NSU MD Research Study <study@updates.meded.studio>";
const EVENT_NAME = "study.enrolled";
const AUTOMATION_NAME = "NSU MD Study \u2014 Reminders & Tips";

const MANIFEST = [{"name":"reminder-week0","subject":"Welcome — start here with your enrollment survey","delayDaysBefore":0,"htmlB64":""},{"name":"tip-01-study-guide","subject":"Tip of the week: Turn your lecture notes into a study guide","delayDaysBefore":7,"htmlB64":""},{"name":"tip-02-flashcards","subject":"Tip of the week: Instant flashcards","delayDaysBefore":14,"htmlB64":""},{"name":"tip-03-learner-type","subject":"Tip of the week: Match the tool to how you learn","delayDaysBefore":14,"htmlB64":""},{"name":"tip-04-qa","subject":"Tip of the week: Ask your notes questions","delayDaysBefore":14,"htmlB64":""},{"name":"reminder-week8","subject":"Time for your Week 8 check-in","delayDaysBefore":7,"htmlB64":""},{"name":"tip-05-active-recall","subject":"Tip of the week: Quiz yourself for active recall","delayDaysBefore":7,"htmlB64":""},{"name":"tip-06-combine-sources","subject":"Tip of the week: Combine multiple sources","delayDaysBefore":14,"htmlB64":""},{"name":"tip-07-connect-concepts","subject":"Tip of the week: Connect concepts across blocks","delayDaysBefore":14,"htmlB64":""},{"name":"tip-08-rapid-review","subject":"Tip of the week: Make a rapid review sheet","delayDaysBefore":14,"htmlB64":""},{"name":"reminder-week16","subject":"Your Week 16 survey is ready","delayDaysBefore":7,"htmlB64":""},{"name":"tip-09-learn-on-the-go","subject":"Tip of the week: Learn on the go","delayDaysBefore":14,"htmlB64":""},{"name":"tip-10-exam-questions","subject":"Tip of the week: Simulate exam questions","delayDaysBefore":14,"htmlB64":""},{"name":"tip-11-feynman","subject":"Tip of the week: Explain it back (the Feynman technique)","delayDaysBefore":21,"htmlB64":""},{"name":"reminder-week24","subject":"Week 24 check-in","delayDaysBefore":7,"htmlB64":""},{"name":"tip-12-cumulative-review","subject":"Tip of the week: Build a cumulative review notebook","delayDaysBefore":21,"htmlB64":""},{"name":"tip-13-weak-spots","subject":"Tip of the week: Target your weak spots","delayDaysBefore":21,"htmlB64":""},{"name":"tip-14-make-it-a-keeper","subject":"Tip of the week: Make it a keeper","delayDaysBefore":7,"htmlB64":""},{"name":"reminder-week32","subject":"Last one — your final study survey","delayDaysBefore":7,"htmlB64":""}];

module.exports = async (req, res) => {
  if ((req.query.setup || "") !== "nsu-go") {
    return res.status(403).json({ ok: false, error: "Add ?setup=nsu-go to run this once." });
  }
  if (!process.env.RESEND_API_KEY) {
    return res.status(503).json({ ok: false, error: "RESEND_API_KEY is not set." });
  }
  const resend = new Resend(process.env.RESEND_API_KEY);
  const report = { ok: true, event: null, templates: [], automation: null, errors: [] };

  try {
    // Guard against duplicates: if the automation already exists, stop.
    try {
      const list = await resend.automations.list();
      const existing = (list.data && (list.data.data || list.data)) || [];
      if (Array.isArray(existing) && existing.some(a => a && a.name === AUTOMATION_NAME)) {
        return res.status(200).json({ ok: true, alreadySetUp: true, message: "Automation already exists. Nothing to do." });
      }
    } catch (e) { /* listing is best-effort */ }

    // 1) Event
    try { await resend.events.create({ name: EVENT_NAME }); report.event = "created"; }
    catch (e) { report.event = "skipped (" + (e && e.message) + ")"; }

    // 2) Templates: ensure all 19 exist AND are published (safe on re-run).
    const existing = {};
    try {
      const tl = await resend.templates.list();
      const items = (tl && tl.data && (tl.data.data || tl.data)) || [];
      if (Array.isArray(items)) for (const it of items) if (it && it.name) existing[it.name] = { id: it.id, status: it.status };
    } catch (e) { /* best-effort */ }

    const ids = [];
    const toPublish = [];
    for (const t of MANIFEST) {
      const ex = existing[t.name];
      if (ex && ex.id) {
        ids.push(ex.id);
        report.templates.push({ name: t.name, id: ex.id, reused: true, status: ex.status });
        if (ex.status !== "published") toPublish.push(ex.id);
        continue;
      }
      const html = Buffer.from(t.htmlB64, "base64").toString("utf8");
      const created = await resend.templates.create({ name: t.name, subject: t.subject, from: FROM, html });
      const id = created && created.data && created.data.id;
      if (!id) { report.errors.push("template " + t.name + ": " + JSON.stringify(created && created.error)); report.ok = false; continue; }
      ids.push(id);
      toPublish.push(id);
      report.templates.push({ name: t.name, id });
      await sleep(250); // throttle: Resend allows 10 requests/second
    }

    // Publish any drafts. publish() returns { error } on failure rather than throwing.
    report.published = 0;
    for (const id of toPublish) {
      let pub;
      try { pub = await resend.templates.publish(id); } catch (e) { pub = { error: { message: String(e && e.message) } }; }
      if (pub && pub.error) { report.errors.push("publish " + id + ": " + JSON.stringify(pub.error)); report.ok = false; }
      else report.published++;
      await sleep(200);
    }
    if (!report.ok) return res.status(500).json(report);
    if (ids.length !== MANIFEST.length) {
      report.ok = false;
      return res.status(500).json(report);
    }

    // 3) Automation (linear: trigger -> send0 -> delay -> send1 -> ...), created DISABLED
    const steps = [{ key: "trigger", type: "trigger", config: { eventName: EVENT_NAME } }];
    const connections = [];
    let prevKey = "trigger";
    MANIFEST.forEach((t, i) => {
      if (t.delayDaysBefore > 0) {
        const dkey = "delay-" + i;
        steps.push({ key: dkey, type: "delay", config: { duration: t.delayDaysBefore + " days" } });
        connections.push({ from: prevKey, to: dkey });
        prevKey = dkey;
      }
      const skey = "send-" + i;
      steps.push({ key: skey, type: "send_email", config: { template: { id: ids[i] }, from: FROM, subject: t.subject } });
      connections.push({ from: prevKey, to: skey });
      prevKey = skey;
    });

    const auto = await resend.automations.create({ name: AUTOMATION_NAME, status: "disabled", steps, connections });
    const autoId = auto && auto.data && auto.data.id;
    if (!autoId) { report.ok = false; report.errors.push("automation: " + JSON.stringify(auto && auto.error)); return res.status(500).json(report); }
    report.automation = autoId;
  } catch (e) {
    report.ok = false;
    report.errors.push("fatal: " + (e && e.message));
    return res.status(500).json(report);
  }

  return res.status(200).json(report);
};
